// Lint configuration for the hand-written JavaScript and TypeScript: the page
// scripts in public/, which the browser loads as plain scripts with no build
// step, the Playwright suite in e2e/, which is type-checked TypeScript, and the
// Node scripts that run the checks and the build.
//
// The Go application is linted by golangci-lint; nothing here touches it.

import js from "@eslint/js";
import globals from "globals";
import tseslint from "typescript-eslint";

export default tseslint.config(
  {
    ignores: [
      "**/node_modules/**",
      "bin/**",
      // Generated by `pnpm run css`, and minified onto one line.
      "public/app.css",
      "e2e/playwright-report/**",
      "e2e/test-results/**",
    ],
  },

  // The caps are measured, not chosen. Re-deriving one means running the rule
  // at max 0 and reading the highest number back. Two things make that
  // unreliable by hand: complexity words its message "has a complexity of 15"
  // while max-params and max-depth say "(3)", so a grep for one shape finds
  // nothing for the other; and a glob passed to eslint is not a glob the shell
  // expanded, so scope it with a file list rather than a pattern.
  //
  // Three ratchets, over every file linted here. Each cap sits at the worst
  // score the tree currently carries, so it holds the line rather than leaving
  // room to grow into, and a function that gains a branch has to lose one
  // somewhere. Lower them as hotspots are simplified; raising one is how a
  // ratchet stops working. `gocyclo -over 4` in CI is the Go counterpart to the
  // first of these.
  //
  // The modified variant scores a whole switch as one decision rather than one
  // per case. It changes no number here, because none of these files switch,
  // and it is stated so the rule reads the same as it does in the sibling
  // repositories rather than differing in a way that looks deliberate.
  {
    rules: {
      complexity: ["error", { max: 4, variant: "modified" }],
      "max-params": ["error", 3],
      "max-depth": ["error", 2],
    },
  },

  // Page scripts. No bundler and no module system: each file is a classic
  // script that publishes what the next one needs on `window`, so the globals
  // it defines and the ones it reads are both declared here.
  {
    files: ["public/**/*.js"],
    extends: [js.configs.recommended],
    languageOptions: {
      ecmaVersion: 2022,
      sourceType: "script",
      globals: {
        ...globals.browser,
        // Loaded from a CDN on the endpoint page only.
        Alpine: "readonly",
        hljs: "readonly",
      },
    },
  },

  // Playwright suite. Type-aware linting, so an implicit `any` reaching an
  // assertion is an error rather than a silently weaker test.
  {
    files: ["e2e/**/*.ts"],
    extends: [js.configs.recommended, tseslint.configs.recommendedTypeChecked],
    languageOptions: {
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname + "/e2e",
      },
    },
    rules: {
      // No assertions: a value that arrives untyped, a JSON body or the
      // clipboard, is parsed with a schema in tests/support/harness.ts, never
      // declared. `as const` is still allowed, since it narrows only a literal
      // the code wrote itself.
      "@typescript-eslint/consistent-type-assertions": [
        "error",
        { assertionStyle: "never" },
      ],
      "@typescript-eslint/no-non-null-assertion": "error",
      "@typescript-eslint/no-explicit-any": "error",
      // Every form of switching the compiler off, not only the default ones.
      "@typescript-eslint/ban-ts-comment": [
        "error",
        {
          "ts-expect-error": true,
          "ts-ignore": true,
          "ts-nocheck": true,
          "ts-check": false,
        },
      ],
    },
  },

  // The Node-side scripts: this file, the checks and the social card under
  // scripts/, and the husky installer.
  {
    files: ["eslint.config.mjs", "scripts/**/*.mjs", ".husky/*.mjs"],
    extends: [js.configs.recommended],
    languageOptions: { globals: globals.node },
  },

  // The social card hands a function to page.evaluate, which runs it in the
  // browser, so that script reads browser globals as well as Node's.
  {
    files: ["scripts/social-card.mjs"],
    languageOptions: { globals: globals.browser },
  },

  // No rule is switched off from inside the code. A comment that disables one
  // is ignored and reported, so an exception has to be made here, in this
  // file, where it is listed with its reason and can be seen.
  {
    linterOptions: {
      noInlineConfig: true,
      reportUnusedInlineConfigs: "error",
    },
  },
);
